applyVoicePromptEdit:
export async function applyVoicePromptEdit(bridge: EvenAppBridge | null = state.activeBridge): Promise<void> {
  const seq = state.voicePromptSeq
  const baseText = state.voiceEditBaseText || state.voiceDraftText
  const instruction = state.voiceEditInstructionText.trim()
  state.voicePromptPhase = 'edit-processing'
  state.voiceCaptureMode = 'prompt-edit'
  await pushVoicePromptEditProcessing(bridge)
  try {
    const total = Math.max(1, state.voiceDraftChunks.length)
    const visibleChunk = state.voiceDraftChunks[state.voiceDraftChunkIndex] ?? state.voiceDraftText
    const result = await editVoicePromptDraft({
      draftText: baseText,
      editInstruction: instruction,
      visibleChunk,
      chunkIndex: state.voiceDraftChunkIndex,
      chunkCount: total,
    })
    if (seq !== state.voicePromptSeq || state.voiceCaptureMode !== 'prompt-edit') {
      logEvent(`Prompt edit stale result ignored (seq ${seq}, active ${state.voicePromptSeq})`)
      return
    }
    const revised = result.revisedText.trim()
    if (!revised) throw new Error('Edit returned empty prompt')
    state.voiceEditUndoStack.push(baseText)
    if (state.voiceEditUndoStack.length > 5) state.voiceEditUndoStack.shift()
    state.voiceDraftText = revised
    state.voiceDraftChunks = buildVoiceDraftChunks(revised)
    state.voiceDraftChunkIndex = 0
    state.voiceEditBaseText = ''
    state.voiceEditInstructionText = ''
    state.voiceCaptureMode = 'prompt'
    state.voicePromptContainerInit = false
    state.audioPipeline?.setSingleUtteranceSeq(undefined)
    await clearPromptDraftSnapshot()
    stopVoicePromptProgress(bridge)
    await showVoicePromptConfirmation(bridge)
    logEvent('Prompt edit applied')
  } catch (err: any) {
    if (seq !== state.voicePromptSeq) return
    state.voiceCaptureMode = 'prompt'
    state.voicePromptPhase = 'review-actions'
    state.voiceNoChoiceIndex = defaultVoicePromptReviewActionIndex(state.voiceEditUndoStack.length > 0, state.voicePromptReviewTarget)
    state.audioPipeline?.setSingleUtteranceSeq(undefined)
    stopVoicePromptProgress(bridge)
    await showVoicePromptReviewActions(bridge, `Edit failed.\n${err?.message ?? err}`)
    logEvent(`Prompt edit failed: ${err?.message ?? err}`)
  }
}
